    def line(self, key):
        i = self.find(key)
        return self.items[key[0]][i][2] if i is not None else None

    def set_line(self, key, line):
        self.items[key[0]][self.find(key)][2] = line

    def delete(self, key):
        items = self.items[key[0]]
